using System.Text;

namespace PdfKnead.EInvoice;

/// <summary>
/// The element rules of the profiles of ZUGFeRD / Factur-X (stage 4, part e2; KONZEPT.md, „Weg für Stufe 4, Teil e“): which elements a
/// profile asks for and allows (how often), which attributes it requires and which code values it takes — the rules FX-SCH-A of the profile
/// validation artefacts of Factur-X 1.09.2 / ZUGFeRD 2.5.2, under their identifiers (Apache-2.0; Zuordnung/profilstruktur.tsv and
/// profilcodes.tsv, generated by profilstruktur.py). Evaluated as Schematron asks them: per pattern only the first rule whose context fits
/// an element; one walk over the tree, the rules found through the tree of their paths (no rule context of these patterns is relative or
/// uses „//“), contexts and counts in the narrow path language (InvoicePath). Only for a CII invoice of one of the five profiles. The reports
/// „not used in the profile“ are hints (part g): PDFK-FX-02, with the place of the element or attribute.
/// </summary>
public static partial class InvoiceRules
{
    /// <summary>The source of the profile rules.</summary>
    public const string ProfileSource = "Factur-X 1.09.2 / ZUGFeRD 2.5.2 (FNFE-MPE, FeRD)";

    private enum StructureKind
    {
        Exactly,
        AtMost,
        AtLeast,
        Attribute,
        Code,
        Unused,
        Empty,
    }

    /// <summary>One check of a rule: its identifier, what it asks, the count, the path counted (or the attribute, or where the code is read: null = the text), the codes.</summary>
    private sealed record StructureCheck(string Id, StructureKind Kind, int Count, InvoicePath? Path, string? Attribute, IReadOnlySet<string>? Codes);

    /// <summary>A rule of a pattern: its context and its checks, in the order of the artefact.</summary>
    private sealed record StructureRule(int Pattern, int Order, InvoicePath Context, List<StructureCheck> Checks);

    /// <summary>The element rules of the profiles: per profile the tree of the paths their contexts name; the rules by identifier; the code
    /// lists by profile and list (also BR-FXEXT-04 of EXTENDED, part e3).</summary>
    private sealed record ProfileStructures(Dictionary<InvoiceProfile, StructureTree> Trees, Dictionary<string, InvoiceRule> Rules,
        Dictionary<(InvoiceProfile, string), HashSet<string>> Codes);

    /// <summary>
    /// The paths the rule contexts of a profile name, as a tree of steps: an element's place is found from its parent's, step by step — no
    /// text per element — and below a place no rule names nothing is asked (FG 842: a path text per element cost 300 bytes each).
    /// </summary>
    private sealed class StructureTree
    {
        private readonly Dictionary<(int Node, string Namespace, string Local), int> _next = [];
        private readonly List<List<StructureRule>?> _rules = [null];   // place 0: above the root

        /// <summary>The place one step below a place; -1 if no rule names it (nor anything below it).</summary>
        public int Step(int node, string ns, string local) => _next.TryGetValue((node, ns, local), out var n) ? n : -1;

        /// <summary>The rules whose context names this place, by pattern and order; null if none.</summary>
        public List<StructureRule>? RulesAt(int node) => _rules[node];

        /// <summary>Adds a rule at the place its context's steps name („/rsm:A/ram:B“, conditions taken off).</summary>
        public void Add(string steps, IReadOnlyDictionary<string, string> prefixes, StructureRule rule)
        {
            var node = 0;
            foreach (var step in steps.Split('/', StringSplitOptions.RemoveEmptyEntries))
            {
                var colon = step.IndexOf(':');
                if (colon <= 0 || !prefixes.TryGetValue(step[..colon], out var ns))
                    throw new InvalidDataException($"profilstruktur.tsv: Schritt ohne bekanntes Präfix: {step}");
                var key = (node, ns, step[(colon + 1)..]);
                if (!_next.TryGetValue(key, out var next))
                {
                    _next[key] = next = _rules.Count;
                    _rules.Add(null);
                }
                node = next;
            }
            (_rules[node] ??= []).Add(rule);
        }

        /// <summary>Puts the rules of each place in the order of the artefact (pattern, then rule).</summary>
        public void Sort()
        {
            foreach (var list in _rules)
                list?.Sort((a, b) => a.Pattern != b.Pattern ? a.Pattern.CompareTo(b.Pattern) : a.Order.CompareTo(b.Order));
        }
    }

    private static InvoiceProfile ProfileOfKey(string key) => key switch
    {
        "MINIMUM" => InvoiceProfile.Minimum,
        "BASICWL" => InvoiceProfile.BasicWl,
        "BASIC" => InvoiceProfile.Basic,
        "EN16931" => InvoiceProfile.En16931,
        "EXTENDED" => InvoiceProfile.Extended,
        _ => throw new InvalidDataException($"profilstruktur.tsv: unbekanntes Profil {key}"),
    };

    /// <summary>
    /// Reads the tables (once, while the rules are built — Build runs during the static initialisation, so no field of another file is used
    /// here). Every path is parsed now: a form outside the narrow language is an error of the table, found by the tests, never at run time.
    /// </summary>
    private static ProfileStructures LoadProfileStructures()
    {
        // the prefixes of the artefacts (a local, not a field: see above)
        var prefixes = new Dictionary<string, string>(StringComparer.Ordinal) { ["rsm"] = Rsm, ["ram"] = Ram, ["udt"] = Udt, ["qdt"] = Qdt };
        var codes = new Dictionary<(InvoiceProfile, string), HashSet<string>>();
        foreach (var line in InvoiceMap.Resource("profilcodes.tsv"))
        {
            if (line.Length == 0 || line[0] == '#') continue;
            var cols = line.Split('\t');
            if (cols.Length != 3) throw new InvalidDataException("profilcodes.tsv: Zeile mit falscher Spaltenzahl");
            var key = (ProfileOfKey(cols[0]), cols[1]);
            if (!codes.TryGetValue(key, out var set)) codes[key] = set = new HashSet<string>(StringComparer.Ordinal);
            set.Add(cols[2]);
        }
        var trees = new Dictionary<InvoiceProfile, StructureTree>();
        var rules = new Dictionary<string, InvoiceRule>(StringComparer.Ordinal);
        var known = new Dictionary<(InvoiceProfile, int, int), StructureRule>();
        foreach (var line in InvoiceMap.Resource("profilstruktur.tsv"))
        {
            if (line.Length == 0 || line[0] == '#') continue;
            var c = line.Split('\t');
            if (c.Length != 10) throw new InvalidDataException("profilstruktur.tsv: Zeile mit falscher Spaltenzahl");
            var profile = ProfileOfKey(c[0]);
            var pattern = int.Parse(c[1], System.Globalization.CultureInfo.InvariantCulture);
            var order = int.Parse(c[2], System.Globalization.CultureInfo.InvariantCulture);
            if (!known.TryGetValue((profile, pattern, order), out var rule))
            {
                rule = new StructureRule(pattern, order, InvoicePath.Parse(c[3], prefixes), []);
                known[(profile, pattern, order)] = rule;
                if (!trees.TryGetValue(profile, out var tree)) trees[profile] = tree = new StructureTree();
                tree.Add(StepsOf(c[3]), prefixes, rule);
            }
            var kind = c[4] switch
            {
                "exactly" => StructureKind.Exactly,
                "atmost" => StructureKind.AtMost,
                "atleast" => StructureKind.AtLeast,
                "attribute" => StructureKind.Attribute,
                "code" => StructureKind.Code,
                "unused" => StructureKind.Unused,
                "empty" => StructureKind.Empty,
                _ => throw new InvalidDataException($"profilstruktur.tsv: unbekannte Art {c[4]}"),
            };
            if (kind == StructureKind.Empty) continue;
            var count = c[7].Length > 0 ? int.Parse(c[7], System.Globalization.CultureInfo.InvariantCulture) : 0;
            var attribute = c[8].StartsWith('@') ? c[8][1..] : null;
            var path = kind is StructureKind.Exactly or StructureKind.AtMost or StructureKind.AtLeast ? InvoicePath.Parse(c[8], prefixes) : null;
            IReadOnlySet<string>? set = kind != StructureKind.Code ? null
                : codes.TryGetValue((profile, c[9]), out var list9) ? list9 : throw new InvalidDataException($"profilcodes.tsv: Liste {c[9]} von {c[0]} fehlt");
            rule.Checks.Add(new StructureCheck(c[5], kind, count, path, attribute, set));
            if (c[5].Length > 0 && !rules.ContainsKey(c[5]))
                rules[c[5]] = StructureRuleOf(c[5], kind, count, c[3], c[8], c[6] == "warning" ? InvoiceRuleSeverity.Warning : InvoiceRuleSeverity.Fatal);
        }
        foreach (var tree in trees.Values) tree.Sort();
        return new ProfileStructures(trees, rules, codes);
    }

    /// <summary>The steps of a path without its conditions („/rsm:A/ram:B[…]/ram:C“ → „/rsm:A/ram:B/ram:C“): the key the rules are found by.</summary>
    private static string StepsOf(string path)
    {
        var sb = new StringBuilder(path.Length);
        var depth = 0;
        foreach (var ch in path)
        {
            if (ch == '[') depth++;
            else if (ch == ']') depth--;
            else if (depth == 0) sb.Append(ch);
        }
        return sb.ToString();
    }

    /// <summary>The element a rule names, for the description: the last two steps of a path, without conditions.</summary>
    private static string Named(string path)
    {
        var steps = StepsOf(path).Split('/', StringSplitOptions.RemoveEmptyEntries);
        return string.Join('/', steps.Skip(Math.Max(0, steps.Length - 2)));
    }

    /// <summary>An element rule with a description of our own (German, English).</summary>
    private static InvoiceRule StructureRuleOf(string id, StructureKind kind, int count, string context, string path, InvoiceRuleSeverity severity)
    {
        var where = Named(context);
        var what = Named(path);
        string Times(bool german) => (count, german) switch
        {
            (1, true) => "einmal",
            (1, false) => "once",
            (_, true) => $"{count}-mal",
            _ => $"{count} times",
        };
        var (german, english) = kind switch
        {
            StructureKind.Exactly => ($"In {where} steht {what} nicht genau {Times(true)}, wie das Profil es verlangt.",
                $"In {where}, {what} does not occur exactly {Times(false)}, as the profile asks."),
            StructureKind.AtMost => ($"In {where} steht {what} öfter als {Times(true)}; das Profil erlaubt nicht mehr.",
                $"In {where}, {what} occurs more often than {Times(false)}; the profile allows no more."),
            StructureKind.AtLeast => ($"In {where} steht {what} nicht mindestens {Times(true)}, wie das Profil es verlangt.",
                $"In {where}, {what} does not occur at least {Times(false)}, as the profile asks."),
            StructureKind.Attribute => ($"Dem Element {where} fehlt das Attribut {path}, das das Profil verlangt.",
                $"The element {where} lacks the attribute {path} the profile asks for."),
            _ => path == "."
                ? ($"Der Wert von {where} steht nicht in der Codeliste des Profils.", $"The value of {where} is not in the code list of the profile.")
                : ($"Der Wert des Attributs {path} an {where} steht nicht in der Codeliste des Profils.",
                    $"The value of the attribute {path} of {where} is not in the code list of the profile."),
        };
        return new InvoiceRule(id, ProfileSource, severity, german, english);
    }

    /// <summary>
    /// Every element rule that an invoice of a profile breaks, by identifier: one walk over the elements (own stack, any depth); each element
    /// is found through the tree of the rule paths; per pattern the first rule whose context fits it is asked. A value read for a code is the text of the element
    /// or the attribute as written (the artefacts compare it so); an empty one passes.
    /// </summary>
    private static Dictionary<string, List<(InvoiceElement Element, string? Value)>> ProfileStructureFindings(Context c, ProfileStructures structures)
    {
        var found = new Dictionary<string, List<(InvoiceElement, string?)>>(StringComparer.Ordinal);
        if (c.Invoice.Kind.Syntax != InvoiceSyntax.Cii || c.Root.Element is not { } root
            || !structures.Trees.TryGetValue(c.Invoice.Kind.Profile, out var tree)) return found;
        // the work the paths may do grows with the size of the invoice, as when reading (FG 826): a shape no test has thought of ends the
        // walk with a hint instead of running for minutes (FG 842)
        var budget = new InvoicePath.Budget(StructureWorkPerElement * Math.Max(Descendants(root).Count(), 1000));
        try
        {
            using (InvoicePath.Use(budget)) Walk(root, tree, found);
        }
        catch (InvoiceXmlException e) when (e.Reason == InvoiceXmlRejection.TooComplex)
        {
            found[StructureAbortId] = [(root, null)];
        }
        return found;
    }

    /// <summary>The nodes the paths of the element rules may visit per element of the invoice (the walk of an ordinary invoice needs a few).</summary>
    internal const long StructureWorkPerElement = 200;

    /// <summary>The rule of PDF-Knead that says the element rules were not asked to the end.</summary>
    private const string StructureAbortId = "PDFK-FX-01";

    /// <summary>The hint of PDF-Knead for what the profile does not use (the reports of the artefacts, which carry no identifier).</summary>
    private const string UnusedId = "PDFK-FX-02";

    private static void Walk(InvoiceElement root, StructureTree tree, Dictionary<string, List<(InvoiceElement, string?)>> found)
    {
        var pending = new Stack<(InvoiceElement Element, int Node)>();
        if (tree.Step(0, root.Namespace, root.Local) is var rootNode and >= 0) pending.Push((root, rootNode));
        var asked = new HashSet<int>();
        // whether an element held the conditions of a step of a context: asked once per element, not once per child (FG 842)
        var memo = new Dictionary<(InvoicePath, int, InvoiceElement), bool>();
        while (pending.Count > 0)
        {
            var (e, at) = pending.Pop();
            for (var i = e.Children.Count - 1; i >= 0; i--)
                if (tree.Step(at, e.Children[i].Namespace, e.Children[i].Local) is var next and >= 0) pending.Push((e.Children[i], next));
            if (tree.RulesAt(at) is not { } candidates) continue;
            asked.Clear();
            var node = new InvoiceNode(e);
            foreach (var rule in candidates)
            {
                if (asked.Contains(rule.Pattern) || !rule.Context.Matches(node, memo)) continue;
                asked.Add(rule.Pattern);   // the first rule of its pattern that fits: the others of the pattern are not asked
                foreach (var check in rule.Checks)
                {
                    string? value = null;
                    var broken = check.Kind switch
                    {
                        StructureKind.Exactly => check.Path!.Count(e) != check.Count,
                        StructureKind.AtMost => check.Path!.Count(e) > check.Count,
                        StructureKind.AtLeast => check.Path!.Count(e) < check.Count,
                        StructureKind.Attribute => e.Attribute(check.Attribute!) is null,
                        StructureKind.Code => (value = check.Attribute is { } a ? e.Attribute(a) : e.Text ?? "") is { Length: > 0 } v && !check.Codes!.Contains(v),
                        // not used in the profile: the element itself (it is there, the context fits it), or an attribute of it that is there
                        StructureKind.Unused => (value = check.Attribute) is null || e.Attribute(value) is not null,
                        _ => false,
                    };
                    if (!broken) continue;
                    var key = check.Kind == StructureKind.Unused ? UnusedId : check.Id;
                    if (!found.TryGetValue(key, out var list)) found[key] = list = [];
                    list.Add((e, check.Kind is StructureKind.Code or StructureKind.Unused ? value : null));
                }
            }
        }
    }

    /// <summary>The element rules of the profiles, one per identifier, each finding with the code as written.</summary>
    private static IEnumerable<RuleCheck> ProfileStructureRules(ProfileStructures structures)
    {
        var rules = structures.Rules.ToList();
        rules.Add(new(StructureAbortId, new InvoiceRule(StructureAbortId, ProfileSource, InvoiceRuleSeverity.Warning,
            "Die Elementregeln des Profils wurden nicht zu Ende geprüft: die Rechnung ist so gebaut, dass die Prüfung zu aufwendig würde.",
            "The element rules of the profile were not checked to the end: the invoice is built so that checking would cost too much.")));
        foreach (var (id, rule) in rules)
        {
            var ident = id;
            yield return new RuleCheck(rule, _ => [],
                c => (c.ProfileFindings ??= ProfileStructureFindings(c, structures)).TryGetValue(ident, out var list)
                    ? list.Select(f => (c.GroupOf(f.Element), c.FieldOf(f.Element), f.Value)) : []);
        }
        // the hint: per element or attribute the profile does not use, with its place and its value as written
        yield return new RuleCheck(new InvoiceRule(UnusedId, HintSource, InvoiceRuleSeverity.Information,
                "Das Profil sieht diese Angabe nicht vor: sie steht in der Rechnung, das Profil nutzt sie nicht.",
                "The profile does not provide for this: it stands in the invoice, the profile does not use it."), _ => [],
            FindWithPlace: c => (c.ProfileFindings ??= ProfileStructureFindings(c, structures)).TryGetValue(UnusedId, out var list)
                ? list.Select(f => (c.GroupOf(f.Element), f.Value is null ? c.FieldOf(f.Element) : null,
                    f.Value is { } attribute ? f.Element.Attribute(attribute) : f.Element.Text, new XmlPlace(f.Element, f.Value)))
                : []);
    }
}
